sp_widget.css:
.co-launchpad {
  position: relative;
  isolation: isolate;
  display: grid;
  grid-template-columns: minmax(0, 1.25fr) minmax(260px, .75fr);
  align-items: center;
  gap: 16px;
  box-sizing: border-box;
  width: 100%;
  min-height: 445px;
  padding: 42px 40px 32px;
  overflow: hidden;
  border: 1px solid rgba(255,255,255,.88);
  border-radius: 28px;
  background:
    radial-gradient(ellipse at 85% 8%, rgba(255,255,255,.96), transparent 36%),
    radial-gradient(ellipse at 62% 90%, rgba(216,196,255,.48), transparent 38%),
    linear-gradient(120deg, #f0e8ff 0%, #e7dbff 48%, #fcecff 100%);
  box-shadow: 0 18px 48px rgba(91,65,125,.10);
  color: #302344;
  font-family: Inter, "Segoe UI", -apple-system, BlinkMacSystemFont, sans-serif;
  -webkit-font-smoothing: antialiased;
}

.co-launchpad *,
.co-launchpad *::before,
.co-launchpad *::after {
  box-sizing: border-box;
}

.co-launch-content {
  position: relative;
  z-index: 2;
  min-width: 0;
  max-width: 650px;
}

.co-orb {
  position: absolute;
  z-index: -1;
  border-radius: 50%;
  pointer-events: none;
}

.co-orb-one {
  width: 320px;
  height: 320px;
  top: -200px;
  right: 8%;
  background: rgba(255,255,255,.42);
}

.co-orb-two {
  width: 240px;
  height: 240px;
  bottom: -180px;
  left: 30%;
  background: rgba(202,177,255,.30);
}

.co-eyebrow {
  display: flex;
  align-items: center;
  gap: 9px;
  margin: 0 0 23px;
  color: #80689e;
  font-size: 9px;
  font-weight: 750;
  letter-spacing: 2px;
}

.co-live-dot {
  width: 8px;
  height: 8px;
  flex: 0 0 8px;
  border-radius: 50%;
  background: #7bbda1;
  box-shadow: 0 0 0 4px rgba(123,189,161,.16);
}

.co-welcome h1 {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 8px;
  margin: 0;
  color: #302344;
  font-size: clamp(29px, 3vw, 40px);
  font-weight: 720;
  letter-spacing: -1.45px;
  line-height: 1.17;
}

.co-welcome-sparkle {
  width: 25px;
  height: 25px;
  flex: 0 0 25px;
  color: #9671d1;
  filter: drop-shadow(0 3px 6px rgba(124,83,183,.22));
}

.co-welcome p {
  margin: 11px 0 23px;
  color: #77658d;
  font-size: 13px;
  line-height: 1.6;
}

.co-message-card {
  display: flex;
  align-items: flex-start;
  gap: 13px;
  width: 100%;
  max-width: 570px;
  padding: 17px;
  border: 1px solid rgba(255,255,255,.88);
  border-radius: 18px;
  background: rgba(255,255,255,.43);
  box-shadow: 0 8px 26px rgba(79,51,113,.055);
  backdrop-filter: blur(18px);
  -webkit-backdrop-filter: blur(18px);
}

.co-message-icon {
  display: flex;
  flex: 0 0 40px;
  align-items: center;
  justify-content: center;
  width: 40px;
  height: 40px;
  border: 1px solid rgba(255,255,255,.9);
  border-radius: 13px;
  background: rgba(255,255,255,.67);
  color: #805ab6;
  font-size: 21px;
}

.co-message-copy {
  flex: 1;
  min-width: 0;
}

.co-message-label {
  margin: 1px 0 7px;
  color: #856ca5;
  font-size: 9px;
  font-weight: 750;
  letter-spacing: 1.35px;
}

.co-message-copy h2 {
  margin: 0 0 6px;
  color: #352549;
  font-size: 16px;
  font-weight: 700;
  line-height: 1.4;
}

.co-message-copy p {
  margin: 0;
  color: #756486;
  font-size: 12px;
  line-height: 1.7;
}

.co-due-detail {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 7px;
  margin-top: 12px;
  color: #624584;
  font-size: 10px;
  font-weight: 650;
  line-height: 1.5;
}

.co-due-separator {
  color: #a693bd;
}

.co-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 10px;
  margin-top: 18px;
}

.co-glass-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 16px;
  min-height: 43px;
  padding: 11px 15px;
  border: 1px solid rgba(255,255,255,.92);
  border-radius: 13px;
  background: rgba(255,255,255,.34);
  box-shadow: 0 5px 18px rgba(67,43,95,.055);
  color: #4d3869 !important;
  font-size: 11px;
  font-weight: 700;
  text-decoration: none !important;
  backdrop-filter: blur(18px);
  -webkit-backdrop-filter: blur(18px);
  transition: transform .2s ease, background .2s ease, box-shadow .2s ease;
}

.co-glass-btn:hover,
.co-glass-btn:focus {
  transform: translateY(-2px);
  background: rgba(255,255,255,.72);
  box-shadow: 0 9px 23px rgba(67,43,95,.12);
  text-decoration: none !important;
}

.co-glass-primary {
  border-color: rgba(255,255,255,.7);
  background: rgba(121,85,177,.82);
  color: #fff !important;
}

.co-glass-primary:hover,
.co-glass-primary:focus {
  background: #7653ad;
  color: #fff !important;
}

.co-btn-arrow {
  font-size: 15px;
  line-height: 1;
}

.co-stats {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 19px;
  margin-top: 24px;
}

.co-stat {
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.co-stat-number {
  color: #39294e;
  font-size: 21px;
  font-weight: 750;
  line-height: 1.2;
  font-variant-numeric: tabular-nums;
}

.co-stat-label {
  color: #806e95;
  font-size: 10px;
  line-height: 1.5;
}

.co-stat-divider {
  width: 1px;
  height: 29px;
  background: rgba(119,91,151,.20);
}

/* Right-side illustration */

.co-artwork {
  position: relative;
  display: flex;
  align-items: center;
  justify-content: center;
  justify-self: stretch;
  width: 100%;
  min-width: 0;
  height: 330px;
}

.co-art-glow {
  position: absolute;
  width: 225px;
  height: 225px;
  border-radius: 50%;
  background: radial-gradient(circle, rgba(255,255,255,.84), rgba(232,216,255,.25) 57%, transparent 73%);
}

.co-art-ring {
  position: absolute;
  border: 1px solid rgba(139,106,188,.19);
  border-radius: 50%;
}

.co-art-ring-outer {
  width: 265px;
  height: 265px;
  box-shadow: 0 0 0 17px rgba(255,255,255,.09);
}

.co-art-ring-inner {
  width: 195px;
  height: 195px;
  border-color: rgba(139,106,188,.26);
  box-shadow: 0 0 0 12px rgba(255,255,255,.10);
}

.co-resource-orb {
  position: relative;
  z-index: 2;
  display: flex;
  align-items: center;
  justify-content: center;
  width: 145px;
  height: 145px;
  border: 1px solid rgba(255,255,255,.95);
  border-radius: 42px;
  background: rgba(255,255,255,.38);
  box-shadow: 0 20px 48px rgba(92,66,135,.12);
  backdrop-filter: blur(20px);
  -webkit-backdrop-filter: blur(20px);
  transform: rotate(-4deg);
}

.co-resource-core {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 112px;
  height: 112px;
  border: 1px solid rgba(255,255,255,.9);
  border-radius: 33px;
  background: linear-gradient(145deg, rgba(255,255,255,.86), rgba(246,235,255,.80));
  box-shadow: inset 0 1px 1px rgba(255,255,255,.95);
}

.co-resource-svg {
  width: 83px;
  height: 83px;
  filter: drop-shadow(0 5px 7px rgba(92,66,135,.10));
}

.co-float-card {
  position: absolute;
  z-index: 4;
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 12px 13px;
  border: 1px solid rgba(255,255,255,.9);
  border-radius: 15px;
  background: rgba(255,255,255,.63);
  box-shadow: 0 12px 30px rgba(79,51,113,.09);
  backdrop-filter: blur(20px);
  -webkit-backdrop-filter: blur(20px);
}

.co-float-book {
  top: 30px;
  left: -3px;
  min-width: 190px;
}

.co-book-icon {
  position: relative;
  display: flex;
  align-items: center;
  width: 31px;
  height: 32px;
}

.co-book-icon span {
  position: absolute;
  width: 13px;
  height: 23px;
  border-radius: 3px 3px 2px 2px;
  box-shadow: 1px 2px 2px rgba(70,45,95,.10);
}

.co-book-green {
  left: 1px;
  top: 4px;
  background: #a9d9a2;
  transform: rotate(-7deg);
}

.co-book-lilac {
  left: 9px;
  top: 2px;
  background: #b9a0eb;
}

.co-book-pink {
  left: 17px;
  top: 7px;
  background: #efaed5;
  transform: rotate(6deg);
}

.co-float-copy {
  display: flex;
  flex-direction: column;
  gap: 4px;
  min-width: 0;
}

.co-float-title {
  color: #5c4679;
  font-size: 9px;
  font-weight: 750;
  letter-spacing: .8px;
  white-space: nowrap;
}

.co-float-subtitle {
  color: #8b7a9e;
  font-size: 10px;
  white-space: nowrap;
}

.co-float-dot {
  width: 7px;
  height: 7px;
  flex: 0 0 7px;
  margin-left: auto;
  border-radius: 50%;
  background: #7bbda1;
  box-shadow: 0 0 0 3px rgba(123,189,161,.14);
}

.co-float-status {
  right: -2px;
  bottom: 43px;
  min-width: 200px;
}

.co-status-icon {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 30px;
  height: 30px;
  flex: 0 0 30px;
  border: 1px solid rgba(255,255,255,.9);
  border-radius: 10px;
  background: #e1f6e9;
  color: #408866;
  font-size: 16px;
  font-weight: 750;
}

.co-art-sparkle {
  position: absolute;
  z-index: 3;
  color: #9874d1;
  text-shadow: 0 3px 12px rgba(130,90,184,.15);
}

.co-art-sparkle-one {
  top: 40px;
  right: 35px;
  font-size: 25px;
}

.co-art-sparkle-two {
  left: 27px;
  bottom: 80px;
  color: #d89bc9;
  font-size: 29px;
}

.co-art-sparkle-three {
  right: 25px;
  top: 132px;
  color: #a88bd5;
  font-size: 16px;
}

.co-art-caption {
  position: absolute;
  bottom: 4px;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  color: #8c77a7;
  font-size: 8px;
  font-weight: 750;
  letter-spacing: 2px;
  white-space: nowrap;
}

.co-caption-line {
  width: 20px;
  height: 1px;
  background: rgba(140,119,167,.45);
}

@media (max-width: 1050px) {
  .co-launchpad {
    grid-template-columns: minmax(0, 1.15fr) minmax(215px, .85fr);
    padding: 34px 28px 28px;
  }

  .co-artwork {
    transform: scale(.9);
  }

  .co-float-book {
    left: -12px;
  }

  .co-float-status {
    right: -12px;
  }
}

@media (max-width: 760px) {
  .co-launchpad {
    grid-template-columns: minmax(0, 1fr);
    padding: 30px 22px;
  }

  .co-launch-content {
    max-width: none;
  }

  .co-artwork {
    height: 250px;
    max-width: 390px;
    justify-self: center;
    margin-top: 8px;
    transform: scale(.88);
  }

  .co-float-book {
    left: 0;
  }

  .co-float-status {
    right: 0;
    bottom: 28px;
  }
}

@media (max-width: 480px) {
  .co-launchpad {
    padding: 25px 17px;
    border-radius: 21px;
  }

  .co-eyebrow {
    font-size: 8px;
    letter-spacing: 1.4px;
  }

  .co-welcome h1 {
    font-size: 29px;
    letter-spacing: -1px;
  }

  .co-welcome-sparkle {
    width: 21px;
    height: 21px;
  }

  .co-message-card {
    padding: 13px;
    gap: 10px;
  }

  .co-message-icon {
    width: 35px;
    height: 35px;
    flex-basis: 35px;
  }

  .co-message-copy h2 {
    font-size: 15px;
  }

  .co-message-copy p {
    font-size: 11px;
  }

  .co-actions {
    flex-direction: column;
  }

  .co-glass-btn {
    justify-content: space-between;
    width: 100%;
  }

  .co-stats {
    gap: 12px;
  }

  .co-stat-number {
    font-size: 19px;
  }

  .co-stat-label {
    font-size: 9px;
  }

  .co-artwork {
    width: 100%;
    transform: scale(.78);
    margin: -8px 0;
  }
}

sp_widget.script:
(function() {
    data.studentName = gs.getUserDisplayName() || "there";
    data.activeCount = 0;
    data.dueSoonCount = 0;
    data.overdueCount = 0;
    data.returnedCount = 0;
    data.nextRental = null;

    var now = new GlideDateTime();
    var nowMs = now.getNumericValue();
    var DAY_MS = 86400000;
    var nearestRental = null;
    var nearestDueMs = null;

    var rentals = new GlideRecord("u_student_rental");
    rentals.addQuery("u_student", gs.getUserID());
    rentals.addQuery("u_status", "active");
    rentals.orderBy("u_due_date");
    rentals.query();

    while (rentals.next()) {
        data.activeCount++;

        var dueValue = rentals.getValue("u_due_date");
        if (!dueValue) {
            continue;
        }

        var dueDate = new GlideDateTime(dueValue);
        var dueMs = dueDate.getNumericValue();
        var daysLeft = Math.ceil((dueMs - nowMs) / DAY_MS);

        if (daysLeft < 0) {
            data.overdueCount++;
        } else if (daysLeft <= 2) {
            data.dueSoonCount++;
        }

        if (nearestRental === null || dueMs < nearestDueMs) {
            nearestRental = {
                assetName: rentals.getDisplayValue("u_asset"),
                number: rentals.getDisplayValue("u_number"),
                dueDate: ""
            };

            // Format the due date as a friendly display string.
            var dateOnly = dueValue.substring(0, 10);
            var parts = dateOnly.split("-");
            var monthNames = [
                "Jan", "Feb", "Mar", "Apr", "May", "Jun",
                "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"
            ];

            if (parts.length === 3) {
                var monthIndex = parseInt(parts[1], 10) - 1;
                var dayNumber = parseInt(parts[2], 10);

                if (monthIndex >= 0 && monthIndex < 12) {
                    nearestRental.dueDate =
                        "Due " + monthNames[monthIndex] + " " + dayNumber;
                }
            }

            nearestDueMs = dueMs;
        }
    }

    data.nextRental = nearestRental;

    var returned = new GlideAggregate("u_student_rental");
    returned.addQuery("u_student", gs.getUserID());
    returned.addQuery("u_status", "returned");
    returned.addAggregate("COUNT");
    returned.query();

    if (returned.next()) {
        data.returnedCount =
            parseInt(returned.getAggregate("COUNT"), 10) || 0;
    }

    if (data.overdueCount > 0) {
        data.messageLabel = "NEEDS YOUR ATTENTION";
        data.messageTitle = "Let's get an overdue return sorted.";
        data.messageBody =
            "One or more rentals are overdue. Check your borrowing shelf for the affected item and return options.";

    } else if (data.dueSoonCount > 0) {
        data.messageLabel = "A LITTLE HEADS-UP";
        data.messageTitle = "Something is due soon.";
        data.messageBody = nearestRental
            ? nearestRental.assetName +
              " is due soon. Check the due date and see whether renewal is available."
            : "You have an upcoming return. Check your borrowing shelf.";

    } else if (data.activeCount > 0) {
        data.messageLabel = "YOUR BORROWING UPDATE";
        data.messageTitle = "You're all set for now.";
        data.messageBody =
            "Keep enjoying your campus resources. Your current rentals are listed below, so you can check their due dates anytime.";

    } else {
        data.messageLabel = "READY FOR YOUR NEXT DISCOVERY?";
        data.messageTitle = "Nothing to return today.";
        data.messageBody =
            "Looking for a textbook, laptop, or lab kit for your next class? Explore the resources available across campus.";
    }
})();
